import React, { useState } from "react";

export default function Students() {

  const [students] = useState([

    {

      id: 1,

      name: "Bhagya Lakshmi",

      email: "bhagya@gmail.com",

      course: "Java Full Stack",

      progress: "85%",

      status: "Active"

    },

    {

      id: 2,

      name: "Sai Kumar",

      email: "sai@gmail.com",

      course: "React JS",

      progress: "75%",

      status: "Active"

    },

    {

      id: 3,

      name: "Priya",

      email: "priya@gmail.com",

      course: "PostgreSQL",

      progress: "90%",

      status: "Completed"

    }

  ]);


  return (

    <div

      style={{

        minHeight: "100vh",

        background: "#f8fafc",

        padding: "40px"

      }}

    >

      <h1

        style={{

          textAlign: "center",

          color: "#0f172a",

          fontSize: "40px"

        }}

      >

        Instructor - Students

      </h1>


      <p

        style={{

          textAlign: "center",

          color: "#64748b",

          marginBottom: "40px"

        }}

      >

        Manage and Track Student Progress

      </p>



      <div

        style={{

          background: "white",

          padding: "25px",

          borderRadius: "20px",

          boxShadow:

          "0 10px 20px rgba(0,0,0,0.1)"

        }}

      >

        <table

          style={{

            width: "100%",

            borderCollapse: "collapse"

          }}

        >

          <thead>

            <tr>

              <th style={th}>ID</th>

              <th style={th}>Name</th>

              <th style={th}>Email</th>

              <th style={th}>Course</th>

              <th style={th}>Progress</th>

              <th style={th}>Status</th>

              <th style={th}>Action</th>

            </tr>

          </thead>


          <tbody>

            {

              students.map((student)=>(

                <tr key={student.id}>

                  <td style={td}>

                    {student.id}

                  </td>


                  <td style={td}>

                    {student.name}

                  </td>


                  <td style={td}>

                    {student.email}

                  </td>


                  <td style={td}>

                    {student.course}

                  </td>


                  <td style={td}>

                    {student.progress}

                  </td>


                  <td style={td}>

                    <span

                      style={{

                        background:

                        student.status==="Active"

                        ? "#22c55e"

                        : "#3b82f6",

                        color:"white",

                        padding:

                        "6px 12px",

                        borderRadius:

                        "20px"

                      }}

                    >

                      {student.status}

                    </span>

                  </td>


                  <td style={td}>

                    <button

                      style={btn}

                      onClick={()=>

                        alert(

                        student.name+

                        "\nCourse : "+

                        student.course+

                        "\nProgress : "+

                        student.progress

                        )

                      }

                    >

                      View

                    </button>

                  </td>

                </tr>

              ))

            }

          </tbody>

        </table>

      </div>

    </div>

  );

}



const th = {

  background:"#2563eb",

  color:"white",

  padding:"15px"

};



const td = {

  textAlign:"center",

  padding:"15px",

  borderBottom:

  "1px solid #e2e8f0"

};



const btn = {

  background:"#2563eb",

  color:"white",

  border:"none",

  padding:"8px 15px",

  borderRadius:"8px",

  cursor:"pointer"

};
